import heapq

class Solution:
    def minGroups(self, intervals: list[list[int]]) -> int:
        intervals.sort()
        pq = []
        for left, right in intervals:
            if pq and pq[0] < left:
                heapq.heappop(pq)
            heapq.heappush(pq, right)
        return len(pq)

class Solution {
public:
    int minGroups(std::vector<std::vector<int>>& intervals) {
        std::sort(intervals.begin(), intervals.end());
        std::priority_queue<int, std::vector<int>, std::greater<int>> pq;
        for (const auto& iv : intervals) {
            if (!pq.empty() && pq.top() < iv[0]) {
                pq.pop();
            }
            pq.push(iv[1]);
        }
        return pq.size();
    }
};

class Solution {
    public int minGroups(int[][] intervals) {
        java.util.Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));
        java.util.PriorityQueue<Integer> pq = new java.util.PriorityQueue<>();
        for (int[] iv : intervals) {
            if (!pq.isEmpty() && pq.peek() < iv[0]) {
                pq.poll();
            }
            pq.offer(iv[1]);
        }
        return pq.size();
    }
}

var minGroups = function(intervals) {
    intervals.sort((a, b) => a[0] - b[0]);
    const starts = intervals.map(iv => iv[0]);
    const ends = intervals.map(iv => iv[1]).sort((a, b) => a - b);
    let endPtr = 0;
    let groups = 0;
    for (let i = 0; i < starts.length; i++) {
        if (starts[i] > ends[endPtr]) {
            endPtr++;
        } else {
            groups++;
        }
    }
    return groups;
};
